23:@Service
24:public class InheritedRates {
25:
26:    private final RateRepository rates;
27:    private final RateLogRepository log;
28:    private final SheetParentRepository parents;
29:    private final SheetSourceRepository sources;
30:
31:    public InheritedRates(RateRepository rates, RateLogRepository log, SheetParentRepository parents,
32:            SheetSourceRepository sources) {
33:        this.rates = rates;
34:        this.log = log;
35:        this.parents = parents;
36:        this.sources = sources;
37:    }
38:
39:    /**
40:     * The sheets whose rates the sheet takes, nearest first: its parents (up to {@link SheetParent#LEVELS}
41:     * levels up), then the sheet it was cloned from, that sheet's parents, its source, and so on; each once.
42:     */
43:    private List<String> inheritedFrom(String sheetId) {
44:        List<String> from = new ArrayList<>();
45:        Set<String> seen = new HashSet<>(Set.of(sheetId));
46:        for (String at = sheetId; at != null; ) {
47:            for (String ancestor : parents.ancestorsOf(at, SheetParent.LEVELS)) if (seen.add(ancestor)) from.add(ancestor);
48:            String source = sources.sourceOf(at);
49:            if (source == null || !seen.add(source)) break;
50:            from.add(source);
51:            at = source;
52:        }
53:        return from;
54:    }
55:
56:    /** The sheet's rates and its ancestors', as they are now. */
